async function markovView(slug:string){
 const box=document.querySelector<HTMLElement>('#markov-view')!;
 if(!session.user){box.innerHTML='<a class="button" href="#account">Sign in to start a private notebook</a>';return;}
 const d=await api(`products/${slug}/observations`);const n=d.states.length;const pos=d.states.map((_:string,i:number)=>({x:220+Math.cos(i/n*2*Math.PI-Math.PI/2)*160,y:170+Math.sin(i/n*2*Math.PI-Math.PI/2)*125}));
 let lines='';d.states.forEach((a:string,i:number)=>d.states.forEach((b:string,j:number)=>{const count=d.counts[a][b];if(count&&i!==j)lines+=`<path d="M${pos[i].x} ${pos[i].y}Q220 170 ${pos[j].x} ${pos[j].y}" fill="none" stroke="#d9aa73" stroke-width="${1+Math.min(count,6)}" opacity=".5" marker-end="url(#arrow)"/><text x="${(pos[i].x+pos[j].x)/2}" y="${(pos[i].y+pos[j].y)/2}" fill="#e5c79e" font-size="10">${count}</text>`;}));
 box.innerHTML=`<div class="markov-layout"><svg viewBox="0 0 440 350" role="img" aria-label="Your observed state transition graph"><defs><marker id="arrow" viewBox="0 0 10 10" refX="30" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#d9aa73"/></marker></defs>${lines}${d.states.map((state:string,i:number)=>`<circle cx="${pos[i].x}" cy="${pos[i].y}" r="29" fill="#263522" stroke="#8e9f70"/><text x="${pos[i].x}" y="${pos[i].y+4}" text-anchor="middle" fill="#d6dfc4" font-size="9">${esc(state)}</text>`).join('')}<text x="220" y="170" text-anchor="middle" fill="#b9996e" font-size="10">${d.observations} observations</text></svg><div><h3>Observed one-step matrix</h3><div class="table-scroll"><table class="matrix"><thead><tr><th>From / to</th>${d.states.map((s:string)=>`<th>${esc(s)}</th>`).join('')}</tr></thead><tbody>${d.states.map((a:string)=>`<tr><th>${esc(a)}</th>${d.states.map((b:string)=>`<td>${d.transition_matrix[a][b]===null?'—':(d.transition_matrix[a][b]*100).toFixed(0)+'%'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">P(i → j) = count(i → j) / all recorded transitions from i. Unobserved rows stay unknown. Small samples are unstable; timing, dose and context are not controlled.</p></div></div><form id="observation-form" class="form-grid"><label>From state<select name="from_state">${d.states.map((s:string)=>`<option>${esc(s)}</option>`).join('')}</select></label><label>To state<select name="to_state">${d.states.map((s:string)=>`<option>${esc(s)}</option>`).join('')}</select></label><label class="full">Context note (optional)<input name="notes" maxlength="500" placeholder="A personal observation, not a medical finding"></label><button class="button">Add private observation</button></form>`;
 bindForm('#observation-form',async data=>{await api(`products/${slug}/observations`,data);notice('Private observation recorded.');await markovView(slug);});
}
function bindForm(selector:string,fn:(d:RecordData)=>Promise<void>){const form=document.querySelector<HTMLFormElement>(selector)!;form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector<HTMLButtonElement>('button[type=submit],button:not([type])');if(b)b.disabled=true;try{await fn(Object.fromEntries(new FormData(form)));}catch(err){notice((err as Error).message,true);}finally{if(b)b.disabled=false;}};}
