async function render(){clearTimeout(searchTimer);renderedRoute=route();const id=++renderID;dispose();dispose=()=>{};shell();const main=document.querySelector<HTMLElement>('#main')!;const [r,slug]=route().split('/');try{updateMetadata(r);if(r==='home'||r==='stories')await home(main,r==='stories');else if(r==='discover')await discoveryPage(main,{api,esc,stats,card,bindCompare,notice});else if(r==='catalog')await catalogue(main);else if(r==='product')await detail(main,slug);else if(r==='account'||r==='setup')await account(main,r==='setup');else if(r==='contribute')await contribute(main);else if(r==='collection')await collectionPage(main);else if(r==='compare')await comparison(main);else if(r==='operations')await operations(main);else if(r==='memento')await renderMemento(main,{api,esc});else if(r==='evidence'){const d=await api('evidence');main.innerHTML=pageTitle('FOLLOW THE REFERENCE','Evidence, with context.','A study is only as useful as its population, exposure and limits.')+`<p class="callout">${esc(d.notice)}</p>`+studiesHTML(d.compounds);}else main.innerHTML='<div class="empty">Page not found. <a href="#catalog">Return to catalogue</a>.</div>';if(id===renderID){mountAtlasExperience();main.classList.add('atlas-arrival');main.focus({preventScroll:true});const anchor=location.hash.slice(1);if(anchor)requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView({block:'start'}));else window.scrollTo(0,0);}}catch(e){main.innerHTML=`<section class="panel"><h1>Could not open this page.</h1><p>${esc((e as Error).message)}</p><a href="#catalog">Return to catalogue</a></section>`;}}
