function heritageHTML(p:RecordData){return `<section class="panel heritage" id="heritage"><div class="heritage-copy"><div class="eyebrow">ORIGIN / CULTURE / LEGACY</div><h2>A place.<br>A point of view.</h2><p>${esc(p.history||p.description)}</p><p class="muted">${esc(p.locality||p.country)}${p.region?' / '+esc(p.region):''}</p>${p.history_source?source(p.history_source):p.origin_source?source(p.origin_source):'<p class="muted">Detailed historical research is not yet curated.</p>'}<p class="muted">The soundscape is original generative art. Disclosed flowers shape airy tones; spices shape soft triangle-wave textures; citrus adds a bright upper note. Product identity sets a stable pentatonic signature. This is not a recording of the drink or a scientific measurement.</p></div><div>${p.image?`<img class="heritage-photo" loading="lazy" src="${esc(p.image)}" alt="${esc(p.brand)} ${esc(p.name)} reference packaging"><p class="muted">${esc(p.image_credit)} · ${esc(p.image_license)} ${p.image_source?`<a href="${esc(p.image_source)}" target="_blank" rel="noopener">Photo provenance ↗</a>`:''}</p>`:bottleSVG(p as any,true)}</div></section>`;}
function pricesHTML(p:RecordData){return `<section class="panel" id="price-history"><div class="eyebrow">THE PRICE NOTEBOOK</div><h2>Price, in context.</h2><p class="muted">Dated price records for a specific bottling, country and seller. No invented historical prices, currency conversions or mixed-format averages.</p>${p.prices?.length?`<label>Comparable series<select id="price-series"></select></label><div id="price-chart"></div><div class="table-scroll"><table><thead><tr><th>Date</th><th>Bottling</th><th>Seller / country</th><th>Price</th><th>Source</th></tr></thead><tbody>${p.prices.map((r:RecordData)=>`<tr><td>${esc(r.date||r.period)}<small>${r.date_precision==='month'?'Publication month · day unknown':r.basis==='historical_ad'?'Document date · open context':r.basis==='archive_capture'?'Archive capture':r.basis==='launch_msrp'?'Recommendation date':'Source view'}</small></td><td>${esc(r.volume_ml)} ml / ${esc(r.abv)}%</td><td>${esc(r.retailer)} / ${esc(r.country)}</td><td>${esc(r.amount)} ${esc(r.currency)}${r.basis==='wholesale_list'?' · wholesale':r.basis==='launch_msrp'?' · launch recommendation':r.basis==='historical_ad'?' · historical publication':''}${r.promotion?' · promotion':''}${r.tax_included===null?' · tax basis unknown':r.tax_included?' · tax included':' · tax not included'}</td><td>${source(r.source)}${r.notes?`<details><summary>Price context</summary><p>${esc(r.notes)}</p></details>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No dated price observations yet. A chart appears once verified records are added in the editorial studio.</div>'}${session.user?.staff?'<a class="button" href="/admin/catalog/priceobservation/add/">Record a sourced price ↗</a>':''}${marketIndexesHTML(p.market_indexes,esc)}</section>`;}
function bindPriceChart(p:RecordData){const select=document.querySelector<HTMLSelectElement>('#price-series');if(!select)return;const groups=new Map<string,RecordData[]>();for(const r of p.prices){const key=[r.variant_id,r.currency,r.country,r.volume_ml,r.abv,r.retailer,r.basis==='wholesale_list'?'wholesale list':r.basis==='launch_msrp'?'manufacturer recommendation':'retail offer',r.tax_included===null?'tax unknown':r.tax_included?'tax included':'tax excluded'].join(' / ');groups.set(key,[...(groups.get(key)||[]),r]);}select.innerHTML=[...groups.keys()].map((k,i)=>`<option value="${i}">${esc(k.substring(k.indexOf(' / ')+3))}</option>`).join('');const draw=()=>{const rows=[...groups.values()][Number(select.value)].slice().sort((a,b)=>Date.parse(a.date||a.period)-Date.parse(b.date||b.period));const lo=Math.min(...rows.map(r=>Number(r.amount))),hi=Math.max(...rows.map(r=>Number(r.amount)));const first=Date.parse(rows[0].date||rows[0].period),last=Date.parse(rows.at(-1)!.date||rows.at(-1)!.period);const points=rows.map(r=>[55+(Date.parse(r.date||r.period)-first)/(last-first||1)*690,170-(Number(r.amount)-lo)/(hi-lo||1)*110]);document.querySelector('#price-chart')!.innerHTML=`<svg class="price-graph" viewBox="0 0 800 230" role="img" aria-label="Source-dated price records"><line x1="50" y1="180" x2="750" y2="180" stroke="#526046"/>${rows.length>1?`<polyline points="${points.map(v=>v.join(',')).join(' ')}" stroke="#d4b081" fill="none" stroke-width="2"/>`:''}${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#e3c59c"><title>${esc(rows[i].date||rows[i].period)}: ${esc(rows[i].amount)} ${esc(rows[i].currency)}</title></circle>`).join('')}<text x="50" y="210">${esc(rows[0].date||rows[0].period)}</text><text x="650" y="210">${esc(rows.at(-1)!.date||rows.at(-1)!.period)}</text><text x="50" y="30">${lo.toFixed(2)} – ${hi.toFixed(2)} ${esc(rows[0].currency)}</text></svg><p class="muted">Lines join recorded observations. Month-only labels retain their precision; missing prices are not reconstructed.</p>`;};select.onchange=draw;draw();}
async function home(main:HTMLElement,storiesOnly=false){
 const features=[{slug:'monkey-47-schwarzwald',label:'Monkey 47',place:'The Black Forest',class:'monkey'},{slug:'roku-japanese-craft',label:'Roku',place:'A Japanese point of view',class:'roku'},{slug:'bombay-sapphire',label:'Bombay Sapphire',place:'A different way to distil',class:'bombay'}];
 main.innerHTML=`${storiesOnly?pageTitle('THE FIELD JOURNAL','Every spirit starts somewhere.','Places, people and processes. Follow the source, then explore the bottle.'):''}<section class="experience-hero"><div class="experience-copy"><div class="eyebrow">THE INDEPENDENT SPIRITS ATLAS / VOL. 04</div><h1>Good spirits.<br><em>Wild stories.</em></h1><p>A field guide for the curious.<br>Places, botanicals & bottles worth knowing.</p><div class="action-row"><a class="button primary" href="#discover">Find your next bottle ↗</a><a class="button subtle" href="#catalog">Browse the collection</a><button class="button subtle" id="listen-home" data-atlas-sound aria-pressed="false">▶ Play the atmosphere</button></div><div class="feature-selector" role="tablist" aria-label="Featured houses">${features.map((f,i)=>`<button role="tab" id="feature-${i}" aria-selected="${i===0}" aria-controls="feature-chapter" data-feature="${i}"><span>0${i+1}</span>${f.label}</button>`).join('')}</div></div><div class="experience-object"><div id="hero-stage" class="hero-stage" aria-label="Featured bottle studio"></div><div class="object-caption"><span id="feature-place"></span><button class="button" id="hero-3d">Enter interactive 3D ↗</button></div></div></section><section class="editorial-chapter" id="feature-chapter" role="tabpanel" aria-labelledby="feature-0"><div class="chapter-heading"><div class="eyebrow">THE STORIES BEHIND THE SPIRITS</div><h2>Place. Process.<br>Personal perspective.</h2><p>Explore a chapter, then follow the references. A producer’s story and a scientific finding have different jobs.</p></div><div class="chapter-body"><div class="chapter-tabs" role="tablist" aria-label="Editorial chapters">${['Origins','Craft','Sound & senses'].map((name,i)=>`<button role="tab" aria-selected="${i===0}" aria-controls="chapter-text" data-chapter="${i}">${name}</button>`).join('')}</div><article id="chapter-text" role="tabpanel"></article></div></section><section class="journey-links"><a href="#catalog"><span>01 / THE COLLECTION</span><h3>Choose with a clearer picture.</h3><p>${stats.products} canonical products. Explore the differences without multiplying formats into products.</p><b>Explore ↗</b></a><a href="#evidence"><span>02 / THE RESEARCH</span><h3>Curiosity, with references.</h3><p>Ingredients, study designs and the questions a bottle cannot answer.</p><b>Read the research ↗</b></a><a href="#contribute"><span>03 / THE COMMUNITY</span><h3>Your eye. Your palate.</h3><p>Contribute a bottle, document a rear label, or share a tasting note.</p><b>Add your perspective ↗</b></a></section>`;
 let current=0,chapter=0,product:RecordData|null=null,version=0;
 const chapterText=()=>{if(!product)return;const p=product;const body=document.querySelector('#chapter-text')!;const texts=[`<div class="eyebrow">${esc(p.locality||p.country)} / ${esc(p.brand)}</div><h3>${esc(p.brand)}. A sense of place.</h3><p>${esc(p.history||p.description)}</p>${p.history_source?source(p.history_source):p.origin_source?source(p.origin_source):'<p class="muted">A detailed historical account is not yet curated.</p>'}`,`<div class="eyebrow">THE MAKING</div><h3>What the process tells us.</h3><p>${esc(p.recipes[0]?.process||'The production process has not yet been curated.')}</p><p class="muted">${esc(p.recipes[0]?.notes||'')}</p>${p.recipes[0]?source(p.recipes[0].source):''}`,`<div class="eyebrow">AN ORIGINAL INTERPRETATION</div><h3>Give the botanicals a voice.</h3><p>Documented flowers shape airy tones. Spices bring texture. Citrus lifts the register. The composition belongs to this product; it does not claim to measure its effects.</p><button class="button primary" id="chapter-sound">Open the mixer ♫</button>`];body.innerHTML=texts[chapter]+`<a class="text-link" href="#product/${esc(p.slug)}">Explore ${esc(p.brand)} ${esc(p.name)} ↗</a>`;document.querySelector<HTMLButtonElement>('#chapter-sound')?.addEventListener('click',openSound);};
 async function choose(index:number){const v=++version;current=index;dispose();dispose=()=>{};const p=await api('products/'+features[index].slug);if(v!==version||!document.contains(main))return;product=p;setSoundSignature(p.slug,p.recipes.flatMap((r:RecordData)=>r.ingredients.map((i:RecordData)=>i.name)));document.querySelectorAll<HTMLButtonElement>('[data-feature]').forEach((b,i)=>b.setAttribute('aria-selected',String(i===index)));document.querySelector('#feature-chapter')!.setAttribute('aria-labelledby','feature-'+index);document.querySelector('#feature-place')!.textContent=features[index].place;document.querySelector('#hero-stage')!.innerHTML=`<div class="hero-photo-object ${features[index].class}"><img src="${esc(p.image)}" alt="${esc(p.brand)} reference bottle photograph"></div>`;document.querySelector<HTMLButtonElement>('#hero-3d')!.textContent='Enter interactive 3D ↗';document.querySelector<HTMLButtonElement>('#hero-3d')!.dataset.running='';chapterText();}
 document.querySelectorAll<HTMLButtonElement>('[data-feature]').forEach(b=>b.onclick=()=>void choose(Number(b.dataset.feature)));
 document.querySelectorAll<HTMLButtonElement>('[data-chapter]').forEach(b=>b.onclick=()=>{chapter=Number(b.dataset.chapter);document.querySelectorAll('[data-chapter]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));chapterText();});
 document.querySelector<HTMLButtonElement>('#listen-home')!.onclick=()=>void toggleSound();
 document.querySelector<HTMLButtonElement>('#hero-3d')!.onclick=async()=>{if(!product)return;const button=document.querySelector<HTMLButtonElement>('#hero-3d')!;if(button.dataset.running==='yes'){button.dataset.running='';await choose(current);return;}const v=++version;const stage=document.querySelector<HTMLElement>('#hero-stage')!;button.disabled=true;try{const cleanup=await mount3D(stage,product as any,'bottle');if(v!==version||!document.contains(stage)){cleanup();return;}dispose=cleanup;button.dataset.running='yes';button.textContent='Return to photograph';}finally{button.disabled=false;}};
 await choose(0);
}
const aromaTags=['floral','juniper','citrus','herbal','spicy','woody','smoky','fruity','vanilla','nutty','sweet','dry','bitter','smooth','warming'];
function reviewFormHTML(){return `<form id="review" class="tasting-form"><div class="eyebrow">YOUR TASTING NOTE</div><fieldset><legend>Overall · 0 to 5 monkeys</legend><div class="monkey-scale">${[0,1,2,3,4,5].map(n=>`<label><input type="radio" name="rating" value="${n}" ${n===5?'checked':''}><span>${n} 🐒</span></label>`).join('')}</div></fieldset><div class="dimension-inputs">${['aroma','taste','finish','value','design'].map(key=>`<label>${key==='value'?'Value for money':key}<select name="${key}"><option value="">Not rated</option>${[0,1,2,3,4,5].map(n=>`<option value="${n}">${n} / 5</option>`).join('')}</select></label>`).join('')}</div><fieldset><legend>Your aroma vocabulary · choose up to eight</legend><div class="tag-picker">${aromaTags.map(t=>`<label><input type="checkbox" name="tags" value="${t}"><span>${t}</span></label>`).join('')}</div></fieldset><div class="form-grid"><label>How did you taste it?<select name="context"><option value="">Prefer not to say</option><option value="neat">Neat</option><option value="ice">On ice</option><option value="tonic">With tonic</option><option value="cocktail">In a cocktail</option></select></label><label>Would you buy it again?<select name="buy_again"><option value="">Not stated</option><option value="yes">Yes</option><option value="no">No</option></select></label></div><label>Your note<textarea name="text" required maxlength="2000" placeholder="Aroma, texture, finish. What made it yours?"></textarea></label><p class="muted">Personal experience, not a verified purchase or a scientific assessment. Notes are reviewed before publication.</p><button class="button primary">Submit tasting note</button></form>`;}
function dimensionsHTML(values:RecordData={}){return `<div class="taste-profile"><div><div class="eyebrow">COMMUNITY PROFILE</div><h3>Five ways to look at it.</h3><p class="muted">Approved notes only. Missing dimensions stay unrated.</p></div><div>${['aroma','taste','finish','value','design'].map(k=>`<div class="taste-row"><span>${k==='value'?'Value for money':k}</span><meter min="0" max="5" value="${values[k]??0}" aria-label="${k} community score"></meter><b>${values[k]===null||values[k]===undefined?'—':Number(values[k]).toFixed(1)}</b><small>${values[k+'_count']||0} notes</small></div>`).join('')}</div></div>`;}
function photoGalleryHTML(p:RecordData){return `<section class="panel packaging-gallery" id="photo-gallery"><div class="section-heading"><div><div class="eyebrow">THE OBJECT / DOCUMENTED PACKAGING</div><h2>Turn the bottle around.</h2></div><button class="button" id="contribute-photo">Contribute a photograph ＋</button></div><p class="muted">Read the real label. Reference packaging can differ by market, size or year; check the image and its source.</p><div class="packaging-tabs" role="tablist" aria-label="Packaging views">${['front','back','detail'].map((v,i)=>`<button role="tab" aria-selected="${i===0}" data-photo-view="${v}" aria-controls="packaging-view">${v==='back'?'Rear label':v==='front'?'Front':'Details'}</button>`).join('')}</div><div id="packaging-pair-control"></div><div id="packaging-view" role="tabpanel"></div><div id="photo-proposal"></div></section>`;}
function bindPhotoGallery(p:RecordData){const photos=[...(p.photos||[]),...(p.image?[{view:'front',url:p.image,credit:p.image_credit,license:p.image_license,source_url:p.image_source,caption:p.image_note}]:[])].filter((x:RecordData,i:number,a:RecordData[])=>a.findIndex(y=>y.url===x.url)===i);
 let selectedPair='',selectedView='front';const pairs=[...new Set<string>(photos.map((x:RecordData)=>x.pair_key).filter(Boolean))].filter(k=>photos.some((x:RecordData)=>x.pair_key===k&&x.view==='front')&&photos.some((x:RecordData)=>x.pair_key===k&&x.view==='back'));if(pairs.length){document.querySelector('#packaging-pair-control')!.innerHTML=`<label>Packaging reference<select id="packaging-pair"><option value="">All documented packaging</option>${pairs.map(k=>{const photo=photos.find((x:RecordData)=>x.pair_key===k);return `<option value="${esc(k)}">${esc(photo?.barcode?'Barcode '+photo.barcode:k)}</option>`;}).join('')}</select></label><p class="muted">Choose a verified front/rear pair to keep the same packaging reference.</p>`;}
 const show=(view:string)=>{selectedView=view;const refs=selectedPair?[]:(p.external_photo_references||[]).filter((x:RecordData)=>x.view===view);const matches=photos.filter((x:RecordData)=>x.view===view&&(!selectedPair||x.pair_key===selectedPair));document.querySelector('#packaging-view')!.innerHTML=matches.length?`<div class="packaging-images">${matches.map((x:RecordData,i:number)=>`<figure><button class="photo-zoom" data-photo-index="${i}" aria-label="Enlarge ${view==='back'?'rear label':view} photograph"><img loading="lazy" src="${esc(x.url)}" alt="${esc(p.brand)} ${view} reference photograph"><span>＋ Inspect label</span></button><figcaption>${esc(x.caption||'Member-supplied packaging reference.')}<br>${esc(x.credit)} · ${esc(x.license)} ${x.source_url?`<a href="${esc(x.source_url)}" rel="noopener" target="_blank">Source ↗</a>`:''}</figcaption></figure>`).join('')}</div>`:`<div class="missing-label"><span>↶</span><h3>${refs.length?'Follow the original photograph.':view==='back'?'The reverse is still undocumented.':view==='front'?'The front awaits curation.':'No detail photograph curated yet.'}</h3><p>${refs.length?'A verified reference is available from its original publisher.':'Help document the actual bottle. Every submitted photograph is reviewed with its source and rights.'}</p><button class="button" id="missing-photo">Add a real photograph</button></div>`;if(refs.length)document.querySelector('#packaging-view')!.insertAdjacentHTML('beforeend',`<div class="external-photo-links">${refs.map((ref:RecordData)=>`<article><a class="button" href="${esc(ref.image_url)}" target="_blank" rel="noopener noreferrer">View ${view==='back'?'rear label':view} at ${esc(ref.publisher)} ↗</a> <a href="${esc(ref.source_page)}" target="_blank" rel="noopener noreferrer">Source page ↗</a><details><summary>About this reference</summary><p>${esc(ref.edition_note)}</p><p>${esc(ref.rights_note)}</p><small>Visually checked ${esc(ref.verified_on)}. External reference; image bytes are hosted by the original publisher.</small></details></article>`).join('')}</div>`);document.querySelector<HTMLButtonElement>('#missing-photo')?.addEventListener('click',proposal);document.querySelectorAll<HTMLButtonElement>('[data-photo-index]').forEach(b=>b.onclick=()=>lightbox(matches[Number(b.dataset.photoIndex)],p));};
 const proposal=()=>{if(!requireMember())return;document.querySelector('#photo-proposal')!.innerHTML=`<form id="photo-form" class="stack"><h3>Document the object.</h3><label>View<select name="view"><option value="back">Rear label</option><option value="front">Front</option><option value="detail">Detail</option></select></label><label>JPEG, PNG or WebP · up to 5 MiB / 16 megapixels<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><div class="form-grid"><label>Photographer / credit<input name="credit" required maxlength="240"></label><label>License or permission statement<input name="license" required maxlength="160" placeholder="e.g. Own photo, CC BY-SA 4.0"></label></div><label>Source or own-photo reference URL<input name="source_url" type="url" required value="${esc(location.origin+location.pathname)}"></label><label>Edition, size and market visible in the image<input name="caption" maxlength="300" placeholder="Describe what is actually visible"></label><label class="rights-confirm"><input type="checkbox" name="rights_confirmed" value="yes" required>I may share this photograph under the stated license.</label><button class="button primary">Submit photograph for review</button><p class="muted">It remains unpublished until an editor checks identity, rights and image quality.</p></form>`;const form=document.querySelector<HTMLFormElement>('#photo-form')!;form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector<HTMLButtonElement>('button')!;button.disabled=true;try{const csrf=document.cookie.split('; ').find(c=>c.startsWith('csrftoken='))?.split('=')[1]||'';const response=await fetch('/api/v1/products/'+p.slug+'/photos',{method:'POST',credentials:'same-origin',headers:{'X-CSRFToken':csrf},body:new FormData(form)});if(!response.ok){const d=await response.json();throw Error(d.error||'Photograph could not be submitted.');}form.innerHTML='<p role="status">Thank you. Your photograph is awaiting editorial review.</p>';}catch(e){notice((e as Error).message,true);}finally{button.disabled=false;}};form.scrollIntoView({behavior:'smooth',block:'center'});};
 document.querySelector<HTMLButtonElement>('#contribute-photo')!.onclick=proposal;document.querySelectorAll<HTMLButtonElement>('[data-photo-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-photo-view]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));show(b.dataset.photoView!);});document.querySelector<HTMLSelectElement>('#packaging-pair')?.addEventListener('change',e=>{selectedPair=(e.target as HTMLSelectElement).value;show(selectedView);});show('front');}
function lightbox(photo:RecordData,p:RecordData){const dialog=document.createElement('dialog');dialog.className='label-lightbox';dialog.setAttribute('aria-label','Inspect '+p.brand+' packaging photograph');dialog.innerHTML=`<div class="lightbox-toolbar"><button class="button" data-zoom="out" aria-label="Zoom out photograph">−</button><output>100%</output><button class="button" data-zoom="in" aria-label="Zoom in photograph">＋</button><button class="button" data-zoom="reset">Fit image</button><button class="button" data-zoom="close" aria-label="Close photograph">✕ Close</button></div><div class="lightbox-image" tabindex="0" aria-label="Photograph. Scroll to move; plus and minus to zoom."><img draggable="false" src="${esc(photo.url)}" alt="${esc(p.brand)} ${esc(photo.view||'front')} label"></div><p>${esc(photo.credit)} · ${esc(photo.license)}</p>`;document.body.append(dialog);let zoom=1;const set=(v:number)=>{zoom=Math.max(.5,Math.min(5,v));const image=dialog.querySelector<HTMLImageElement>('img')!;image.style.width=(zoom*100)+'%';image.style.height=(zoom*100)+'%';dialog.querySelector('output')!.textContent=Math.round(zoom*100)+'%';};dialog.querySelectorAll<HTMLButtonElement>('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='close')dialog.close();else set(b.dataset.zoom==='in'?zoom+.25:b.dataset.zoom==='out'?zoom-.25:1);});const surface=dialog.querySelector<HTMLElement>('.lightbox-image')!;let origin:{x:number,y:number,left:number,top:number}|null=null;surface.onpointerdown=e=>{if(zoom<=1)return;origin={x:e.clientX,y:e.clientY,left:surface.scrollLeft,top:surface.scrollTop};surface.setPointerCapture(e.pointerId);};surface.onpointermove=e=>{if(origin){surface.scrollLeft=origin.left-(e.clientX-origin.x);surface.scrollTop=origin.top-(e.clientY-origin.y);}};surface.onpointerup=()=>origin=null;surface.onpointercancel=()=>origin=null;surface.onkeydown=e=>{if(['+','=','-','0'].includes(e.key)){e.preventDefault();set(e.key==='0'?1:zoom+(e.key==='-'?-.25:.25));}};dialog.onclose=()=>dialog.remove();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});dialog.showModal();}

// Arrow navigation supplements native Tab / Enter activation for tab groups.
document.addEventListener('keydown',e=>{const tab=(e.target as Element).closest<HTMLButtonElement>('[role=tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;const tabs=Array.from(tab.closest('[role=tablist]')!.querySelectorAll<HTMLButtonElement>('[role=tab]'));let i=tabs.indexOf(tab);i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();tabs[i].focus();tabs[i].click();});
